// Shared by the recompiled game code (generated by tools/recomp/recomp.py) and the runtime.
//
// Execution contract, identical to mGBA's interpreter so both can hand over at any instruction:
//  - while an instruction runs, gprs[15] = its address + 2 * width and prefetch[] holds the next two
//    opcodes;
//  - between instructions the state is exactly what ThumbStep/ARMStep leaves behind;
//  - a chunk function returns 1 when it stops (event due, branch out of the chunk, mode change) and 0
//    when it has no code for the requested address.
#pragma once
#include <stdint.h>

#include <mgba/internal/arm/arm.h>
#include <mgba/internal/arm/isa-arm.h>
#include <mgba/internal/arm/isa-inlines.h>
#include <mgba/internal/arm/isa-thumb.h>

#if defined(__GNUC__) || defined(__clang__)
#define RC_INLINE inline __attribute__((always_inline))
#define RC_UNLIKELY(x) __builtin_expect(!!(x), 0)
#else
#define RC_INLINE __forceinline
#define RC_UNLIKELY(x) (x)
#endif

struct RecompChunk {
	uint32_t start, end;  // guest address range [start, end)
	int thumb;
	int (*fn)(struct ARMCore* cpu, uint32_t pc);
	const uint8_t* guard;  // code copied to RAM (or the BIOS): expected bytes of [start, end)
	uint32_t guardLen;
};

// Before each instruction: the pipeline state the interpreter would have.
#define RC_PRE(PC, P0, P1) \
	cpu->gprs[ARM_PC] = (int32_t) (PC); \
	cpu->prefetch[0] = (P0); \
	cpu->prefetch[1] = (P1);

// After each instruction: hand control back when an event (IRQ, timer, DMA, video) is due.
#define RC_EVENT() \
	if (RC_UNLIKELY(cpu->cycles >= cpu->nextEvent)) return 1;

// Thumb instruction that may write PC. NEXT = gprs[15] when it did not branch.
#define RC_EXIT_IF_PC(NEXT) \
	if ((uint32_t) cpu->gprs[ARM_PC] != (NEXT) || cpu->executionMode != MODE_THUMB) return 1;

// Thumb branch whose target is in this chunk: TPC = gprs[15] after taking it.
#define RC_BRANCH(NEXT, TPC, LABEL) \
	if ((uint32_t) cpu->gprs[ARM_PC] != (NEXT)) { \
		if ((uint32_t) cpu->gprs[ARM_PC] == (TPC) && cpu->cycles < cpu->nextEvent) goto LABEL; \
		return 1; \
	}

#define RC_EXIT_IF_PC_ARM(NEXT) \
	if ((uint32_t) cpu->gprs[ARM_PC] != (NEXT) || cpu->executionMode != MODE_ARM) return 1;

#define RC_BRANCH_ARM(NEXT, TPC, LABEL) \
	if ((uint32_t) cpu->gprs[ARM_PC] != (NEXT) || cpu->executionMode != MODE_ARM) { \
		if ((uint32_t) cpu->gprs[ARM_PC] == (TPC) && cpu->executionMode == MODE_ARM && \
		    cpu->cycles < cpu->nextEvent) goto LABEL; \
		return 1; \
	}
